<script>
export default {
  props: {
    // Chat mode: projects are derived from the chat, its subtasks and chat.pr_view
    chat: { type: Object, default: null },
    // Standalone mode (e.g. embedded in GitView): project to compare branches for
    project: { type: Object, default: null },
    // Explicit source/target comparison requested by the host (Repository view
    // worktree "Compare with current branch"). `token` makes every click a new
    // request, even when the branch pair is unchanged.
    compareRequest: { type: Object, default: null }
  },
  emits: ['refresh', 'select-branch', 'comment', 'change-column', 'new-chat', 'chat-message', 'open-chat', 'jump-to-message', 'context-menu-notice', 'context-menu-error'],
  data() {
    return {
      loadingChanges: false,
      loadingStep: '',
      selectedProjectId: null,
      branchesByProject: {},
      changesByProject: {},
      changeCountByProject: {},
      // per-project branch pair: projectId -> { from, to }
      //   from = source branch (from_branch, left selector) - the branch that will be merged
      //   to   = target branch (to_branch, right selector) - where the source is merged into
      branchSelectionByProject: {},
      // A pair requested while the projects/branches are still loading. It is
      // applied again after `initBranchSelection`, so an in-flight
      // `loadAllProjects` cannot overwrite an explicit "Compare with current".
      pendingBranchComparison: null,
      // Review the uncommitted working tree against the current branch instead
      // of comparing two branches.
      localReview: false,
      // Local review reads only the files staged in the index (same default as
      // the Validator), so both lists describe what the next commit contains.
      localStagedOnly: true,
      showAddProjectdropdown: false,
      // Pending merge/rebase conflict state of the selected project ("git
      // manager" surface: the chat's changes panel detects it too)
      conflictState: null,
      showConflicts: false
    }
  },
  computed: {
    chatProject() {
      return this.chat ? this.$chats.chatProject(this.chat) : null
    },

    relatedProjects() {
      if (!this.chat) return []

      const related = new Map()
      const state = this.chatProject.$state

      // Get child projects from state getter
      const childProjects = state.childProjects || []
      childProjects.forEach(p => {
        const id = this.projId(p)
        if (id) related.set(id, p)
      })

      // Get linked projects from state getter
      const linkedProjects = state.linkedProjects || []
      linkedProjects.forEach(p => {
        const id = this.projId(p)
        if (id) related.set(id, p)
      })

      return Array.from(related.values())
    },

    activeProjectIds() {
      // First priority: use pr_view if it exists
      if (this.chat?.pr_view?.pull_requests) {
        return Object.keys(this.chat.pr_view.pull_requests)
      }

      // Fallback: use chat's own project_id or owner_project_id for first load
      const chatProjectId = this.chat?.project_id || this.chat?.owner_project_id
      if (chatProjectId) return [chatProjectId]

      // Standalone: the project given as prop
      const projectId = this.project ? this.projId(this.project) : null
      return projectId ? [projectId] : []
    },

    projectsWithBranches() {
      return this.activeProjectIds
        .map(id => this.$storex.projects.allProjectsById?.[id])
        .filter(p => p && Array.isArray(this.branchesByProject[this.projId(p)]) && this.branchesByProject[this.projId(p)].length > 0)
    },

    availableProjectsToAdd() {
      return this.relatedProjects.filter(p => {
        const id = this.projId(p)
        return !this.activeProjectIds.includes(id)
      })
    },

    selectedProject() {
      if (!this.selectedProjectId) return null
      return this.$storex.projects.allProjectsById?.[this.selectedProjectId] || this.project || null
    },

    selectedBranches() {
      return this.branchesByProject[this.selectedProjectId] || []
    },

    /** The selected project has an unresolved merge/rebase conflict */
    hasConflicts() {
      return !!this.conflictState?.in_progress
    },

    conflictCount() {
      return this.conflictState?.unresolved_count
        ?? this.conflictState?.conflict_count
        ?? 0
    },

    // Left selector: source branch (from_branch) - what will be merged
    fromBranch() {
      return this.branchSelectionByProject[this.selectedProjectId]?.from || 'main'
    },

    // Right selector: target branch (to_branch) - where the source is merged into
    toBranch() {
      return this.branchSelectionByProject[this.selectedProjectId]?.to || 'local'
    },

    cacheKey() {
      if (!this.selectedProjectId) return null
      // Local review: the working tree against the current branch
      if (this.localReview) return this.localCacheKey
      return `${this.selectedProjectId}:${this.fromBranch}:${this.toBranch}`
    },

    /** Cache key of the local review (the staged filter changes the payload) */
    localCacheKey() {
      return `${this.selectedProjectId}:local:${this.localStagedOnly ? 'staged' : 'all'}`
    },

    cachedRepoChanges() {
      return this.cacheKey ? (this.changesByProject[this.cacheKey] || null) : null
    }
  },
  watch: {
    chat(newChat) {
      if (newChat?.id) this.loadAllProjects()
    },
    project(newProject, previousProject) {
      if (!newProject) return
      if (newProject.project_id === previousProject?.project_id) return
      if (newProject.project_id !== this.selectedProjectId) this.loadAllProjects()
    },
    selectedProjectId(id) {
      if (id && !this.cachedRepoChanges) {
        this.loadChangesForProject(id)
      }
      if (id) {
        this.loadConflictStateForProject(
          this.$storex.projects.allProjectsById?.[id]
        )
      }
    },
    fromBranch() {
      this.loadChangesForProject(this.selectedProjectId)
    },
    toBranch() {
      this.loadChangesForProject(this.selectedProjectId)
    },
    localReview() {
      this.loadChangesForProject(this.selectedProjectId, true)
    },
    // The staged filter narrows the local change list: reload it
    localStagedOnly() {
      if (this.localReview) this.loadChangesForProject(this.selectedProjectId, true)
    },
    compareRequest(value) {
      if (!value?.from || !value?.to) return
      this.compareBranches(value.from, value.to)
    }
  },
  mounted() {
    if (this.chat || this.project) this.loadAllProjects()
    document.addEventListener('click', this.closedropdown)
  },
  beforeUnmount() {
    document.removeEventListener('click', this.closedropdown)
  },
  methods: {
    projId({ project_id, owner_project_id } = {}) {
      return project_id || owner_project_id
    },

    toggleAddProjectdropdown() {
      this.showAddProjectdropdown = !this.showAddProjectdropdown
    },

    closedropdown(event) {
      const headerBtn = event.target.closest('[title="Add more projects"]')
      const dropdown = event.target.closest('.dropdown-content bg-base-100')
      if (!headerBtn && !dropdown) {
        this.showAddProjectdropdown = false
      }
    },

    setChangesCache(key, value) {
      this.changesByProject = { ...this.changesByProject, [key]: value }
    },

    setChangeCount(projectId, count) {
      this.changeCountByProject = { ...this.changeCountByProject, [projectId]: count }
    },

    setBranches(projectId, branches) {
      this.branchesByProject = { ...this.branchesByProject, [projectId]: branches }
    },

    async loadBranchesForProject(project) {
      const id = this.projId(project)
      if (!id) return false

      try {
        const { branches, active_branch: activeBranch } = await project.$api.repo.branches()
        if (Array.isArray(branches) && branches.length > 0) {
          this.setBranches(id, branches)
          this.initBranchSelection(id, branches, activeBranch)
          return true
        }
        return false
      } catch {
        return false
      }
    },

    /**
     * Detect a pending merge/rebase conflict for a project.
     *
     * The changes panel is the git management surface of the vibe/chat view, so
     * it must offer the same conflict resolution as the git view. Only the
     * summary is loaded here: the resolver fetches the conflict content when
     * the user opens it.
     *
     * @param {Object} project - Project owning the repository.
     */
    async loadConflictStateForProject(project) {
      const api = project?.$api
      if (!api || !project) return
      try {
        const state = await api.repo.conflicts({ include_content: false })
        if (this.projId(project) === this.selectedProjectId) {
          this.conflictState = state || null
        }
      } catch {
        if (this.projId(project) === this.selectedProjectId) {
          this.conflictState = null
        }
      }
    },

    openConflictResolver() {
      if (!this.selectedProject?.$api) return
      this.showConflicts = true
    },

    onConflictsUpdated(state) {
      this.conflictState = state || null
    },

    async onConflictFinished() {
      this.showConflicts = false
      await this.loadConflictStateForProject(this.selectedProject)
      this.$emit('refresh')
    },

    async loadAllProjects() {
      if (!this.activeProjectIds.length) return
      this.loadingChanges = true
      this.branchesByProject = {}
      this.changesByProject = {}
      this.changeCountByProject = {}
      this.branchSelectionByProject = {}

      try {
        // Load branches for all active projects from pr_view
        for (const projectId of this.activeProjectIds) {
          const project = this.$storex.projects.allProjectsById?.[projectId]
          if (!project) continue

          this.loadingStep = `Loading branches for ${project.project_name}...`
          await this.loadBranchesForProject(project)
        }

        // Load changes for projects with branches
        for (const proj of this.projectsWithBranches) {
          const id = this.projId(proj)
          this.loadingStep = `Loading changes for ${proj.project_name}...`
          await this.loadChangesForProject(id)
        }

        // Select first project if none selected. An explicit comparison
        // requested while loading wins over the default first project.
        const pending = this.pendingBranchComparison
        const first = this.projectsWithBranches[0]
        if (pending?.projectId) {
          this.selectedProjectId = pending.projectId
        } else {
          this.selectedProjectId = first ? this.projId(first) : null
        }
        const selected = this.$storex.projects.allProjectsById?.[this.selectedProjectId]
        if (selected) await this.loadConflictStateForProject(selected)

      } finally {
        this.loadingChanges = false
        this.loadingStep = ''
        // The explicit comparison has been applied by now: a later branch
        // reload must not keep reusing a stale pending pair.
        this.pendingBranchComparison = null
      }
    },

    async addProjectToPanel(project) {
      if (!this.chat) return
      const id = this.projId(project)
      if (!id) return

      // Create entry in pr_view with empty config
      const updatedChat = {
        ...this.chat,
        pr_view: {
          ...(this.chat.pr_view || {}),
          pull_requests: {
            ...(this.chat.pr_view?.pull_requests || {}),
            [id]: {
              url: '',
              fromBranch: '',
              toBranch: ''
            }
          }
        }
      }

      // Save to storage immediately
      await this.$storex.chats.saveChat(updatedChat)
      this.showAddProjectdropdown = false

      // Load branches for newly added project
      this.loadingStep = `Loading branches for ${project.project_name}...`
      const hasBranches = await this.loadBranchesForProject(project)

      if (hasBranches) {
        // Load changes for added project
        this.loadingStep = `Loading changes for ${project.project_name}...`
        await this.loadChangesForProject(id)

        // Select the newly added project
        this.selectedProjectId = id
      }
    },

    async removeProjectFromPanel(projectId) {
      if (!this.chat) return
      const project = this.$storex.projects.allProjectsById?.[projectId]
      if (!project) return

      // Remove from pr_view
      const { [projectId]: _, ...remainingProjects } = this.chat.pr_view?.pull_requests || {}
      const updatedChat = {
        ...this.chat,
        pr_view: {
          ...(this.chat.pr_view || {}),
          pull_requests: remainingProjects
        }
      }

      // Save to storage immediately
      await this.$storex.chats.saveChat(updatedChat)

      // Clear data for removed project
      const keysToDelete = Object.keys(this.changesByProject).filter(key => 
        key.startsWith(`${projectId}:`)
      )
      const newChanges = { ...this.changesByProject }
      keysToDelete.forEach(key => delete newChanges[key])
      this.changesByProject = newChanges

      // Clear other data
      const { [projectId]: __, ...restBranches } = this.branchesByProject
      const { [projectId]: ___, ...restCounts } = this.changeCountByProject
      const { [projectId]: ____, ...restSelection } = this.branchSelectionByProject

      this.branchesByProject = restBranches
      this.changeCountByProject = restCounts
      this.branchSelectionByProject = restSelection

      // Reset selection if removed project is selected
      if (this.selectedProjectId === projectId) {
        const first = this.projectsWithBranches[0]
        this.selectedProjectId = first ? this.projId(first) : null
      }
    },

    initBranchSelection(projectId, branches, activeBranch = '') {
      const prConfig = this.chat?.pr_view?.pull_requests?.[projectId]
      const pending = this.pendingBranchComparison?.projectId === projectId
        ? this.pendingBranchComparison
        : null
      const current = activeBranch && branches.includes(activeBranch)
        ? activeBranch
        : (branches[0] || 'main')
      this.branchSelectionByProject = {
        ...this.branchSelectionByProject,
        [projectId]: {
          // from = source (left selector), to = target (right selector)
          from: pending?.from || prConfig?.fromBranch || current,
          to: pending?.to || prConfig?.toBranch || 'local'
        }
      }
    },

    async loadChangesForProject(projectId, force = false) {
      if (!projectId) return
      const project = this.$storex.projects.allProjectsById?.[projectId]
      if (!project) return

      const sel = this.branchSelectionByProject[projectId] || {}
      const from = sel.from || 'main'
      const to = sel.to || 'local'
      const local = this.localReview
      const key = local
        ? `${projectId}:local:${this.localStagedOnly ? 'staged' : 'all'}`
        : `${projectId}:${from}:${to}`

      if (!force && this.changesByProject[key]) return

      try {
        let changes
        if (local) {
          // `local` on both sides makes the backend resolve the changes
          // against the checked out branch, without an extra repository info
          // request (which reads every worktree status).
          changes = await project.$api.repo.changes({
            from_branch: 'local',
            to_branch: 'local',
            // Same staged check as the Validator: only the index is reviewed
            staged: this.localStagedOnly
          })
        } else {
          changes = await project.$api.repo.changes({
            from_branch: from,
            to_branch: to
          })
        }
        this.setChangesCache(key, changes)
        const count = Object.keys(changes?.branch_file_and_commits || {}).length
        this.setChangeCount(projectId, count)
      } catch (ex) {
        // Empty/identical branch pairs (or a git error) must not lock the user
        // out of the branch selectors: cache an empty, valid result instead.
        console.warn('Unable to load branch changes:', ex)
        this.setChangesCache(key, {
          repo_path: project.abs_project_path || '',
          branch_file_and_commits: {},
          compare_type: local ? 'local' : 'branch'
        })
        this.setChangeCount(projectId, 0)
      }
    },

    /**
     * Switch the panel to "local changes vs current branch".
     *
     * Used by the git view's "Local changes" action: the Review tab can be
     * opened directly on the uncommitted changes without touching the branch
     * selectors.
     */
    enableLocalReview() {
      if (this.localReview) {
        // Already in local mode: just refresh the working tree snapshot
        if (this.selectedProjectId) {
          this.loadChangesForProject(this.selectedProjectId, true)
        }
        return
      }
      // The `localReview` watcher loads the changes
      this.localReview = true
    },

    /** Toggle between the branch comparison and the local changes review */
    toggleLocalReview() {
      this.localReview = !this.localReview
    },

    /** Left selector changed: source branch (from_branch) */
    onFromBranchChanged(branch) {
      if (!this.selectedProjectId) return
      this.branchSelectionByProject = {
        ...this.branchSelectionByProject,
        [this.selectedProjectId]: {
          ...this.branchSelectionByProject[this.selectedProjectId],
          from: branch
        }
      }
      this.saveBranchConfig()
      this.loadChangesForProject(this.selectedProjectId)
    },

    /** Right selector changed: target branch (to_branch) */
    onToBranchChanged(branch) {
      if (!this.selectedProjectId) return
      this.branchSelectionByProject = {
        ...this.branchSelectionByProject,
        [this.selectedProjectId]: {
          ...this.branchSelectionByProject[this.selectedProjectId],
          to: branch
        }
      }
      this.saveBranchConfig()
      this.loadChangesForProject(this.selectedProjectId)
    },

    onBranchSelected({ fromBranch, toBranch }) {
      this.onFromBranchChanged(fromBranch)
      this.onToBranchChanged(toBranch)
      this.$emit('select-branch', { fromBranch, toBranch })
    },

    /**
     * Open a specific branch comparison in the Review panel.
     *
     * Used by the Repository view's worktree "Compare with current branch"
     * action: it selects the project, leaves local-review mode and loads the
     * requested source → target pair.
     *
     * @param {string} fromBranch - Source branch (worktree branch).
     * @param {string} toBranch - Target branch (current branch).
     */
    async compareBranches(fromBranch, toBranch) {
      const project = this.project
        || this.$storex.projects.allProjectsById?.[this.selectedProjectId]
        || null
      const projectId = (this.project ? this.projId(this.project) : null)
        || this.selectedProjectId
        || (project ? this.projId(project) : null)
      if (!projectId || !fromBranch || !toBranch) return

      const pair = { projectId, from: fromBranch, to: toBranch }
      this.pendingBranchComparison = pair
      this.localReview = false
      // Set the pair BEFORE changing the selected project: the
      // `selectedProjectId` watcher then loads the right comparison.
      this.branchSelectionByProject = {
        ...this.branchSelectionByProject,
        [projectId]: {
          ...(this.branchSelectionByProject[projectId] || {}),
          from: fromBranch,
          to: toBranch
        }
      }
      this.selectedProjectId = projectId

      // `loadAllProjects` may still be loading the branch list (and
      // `initBranchSelection` would reset the pair). Wait for it and apply the
      // explicit pair again before loading the comparison.
      if (project && !(this.branchesByProject[projectId] || []).length) {
        await this.loadBranchesForProject(project)
        this.branchSelectionByProject = {
          ...this.branchSelectionByProject,
          [projectId]: {
            ...(this.branchSelectionByProject[projectId] || {}),
            from: fromBranch,
            to: toBranch
          }
        }
      }

      await this.loadChangesForProject(projectId, true)
      // Keep the pending pair while `loadAllProjects` is still running: its
      // own branch load could initialize the selectors again afterwards.
      if (!this.loadingChanges && this.pendingBranchComparison === pair) {
        this.pendingBranchComparison = null
      }
    },

    onOpenFile(filePath) {
      if (!filePath) return
      this.$ui.openProjectFile(filePath)
    },

    saveBranchConfig() {
      if (!this.chat || !this.selectedProjectId) return
      const sel = this.branchSelectionByProject[this.selectedProjectId]
      if (!sel) return
      const updatedChat = {
        ...this.chat,
        pr_view: {
          ...(this.chat.pr_view || {}),
          pull_requests: {
            ...(this.chat.pr_view?.pull_requests || {}),
            [this.selectedProjectId]: {
              url: '',
              fromBranch: sel.from,
              toBranch: sel.to
            }
          }
        }
      }
      this.$storex.chats.saveChat(updatedChat)
    },

    changeCountClass(projectId) {
      const count = this.changeCountByProject[projectId] || 0
      if (count === 0) return 'badge-ghost'
      if (count < 5) return 'badge-info'
      if (count < 10) return 'badge-warning'
      return 'badge-error'
    }
  }
}
</script>
